{"root": {"children": [{"type": "codeblock", "version": 1, "language": "apex", "code": "public with sharing class AccountTriggerHandler {
    public static Boolean bypass = false;

    public static void beforeInsert(List<Account> records) {
        if (bypass) return;
        for (Account acc : records) {
            // never SOQL/DML inside this loop
            acc.Rating = acc.AnnualRevenue > 1000000 ? 'Hot' : 'Warm';
        }
    }

    public static void afterUpdate(Map<Id, Account> oldMap,
                                   Map<Id, Account> newMap) {
        List<Account> changed = new List<Account>();
        for (Account acc : newMap.values()) {
            if (acc.OwnerId != oldMap.get(acc.Id).OwnerId) {
                changed.add(acc);
            }
        }
        if (!changed.isEmpty()) OwnerSync.enqueue(changed);
    }
}", "caption": ""}, {"children": [{"detail": 0, "format": 0, "mode": "normal", "style": "", "text": "Gotchas", "type": "text", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "type": "heading", "tag": "h2", "version": 1}, {"children": [{"detail": 0, "format": 0, "mode": "normal", "style": "", "text": "The bypass flag is for data migrations and tests only — every production use deserves a code comment explaining itself. And afterUpdate compares old to new before doing anything: change detection is what keeps recursion away.", "type": "text", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "type": "paragraph", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "type": "root", "version": 1}}

